function tokenize(text) {
  const m = (text || '').toLowerCase().match(/[а-яёa-z0-9]+/g) || [];
  return m.filter(t => t.length > 2 && !STOPWORDS.has(t));
}
const payload = JSON.parse($input.first().json.payload);
const qTokens = new Set(tokenize(payload.question));
const scored = payload.docs.map(d => {
  const dTokens = new Set(tokenize(d.text));
  let overlap = 0; for (const t of qTokens) if (dTokens.has(t)) overlap++;
  return {id: d.id, overlap};
});
scored.sort((a,b) => b.overlap - a.overlap);
return [{json: {...payload, keyword_rank_live: scored.map(s => s.id)}}];

const d = $('Keyword overlap (ранжирование по словам)').first().json;
const qvec = $input.first().json.data[0].embedding;
function cosine(a, b) {
  let dot=0, na=0, nb=0;
  for (let i=0;i<a.length;i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  return (na && nb) ? dot/(Math.sqrt(na)*Math.sqrt(nb)) : 0;
}
const scored = d.docs.map(doc => ({id: doc.id, sim: cosine(qvec, doc.embedding)}));
scored.sort((a,b) => b.sim - a.sim);
return [{json: {...d, vector_rank_live: scored.map(s => s.id)}}];

const d = $input.first().json;
const body = {
  model: 'typesafe/jev-1.13',
