const d = $('Cosine ranking (вектор)').first().json;
const jev = $input.first().json;
const ans = (jev.answers || {}).type || {};
const choice = ans.choice;
const confidence = ans.confidence;
const w_keyword = choice === 'exact_fact' ? 0.75 : (choice === 'semantic' ? 0.25 : 0.5);
return [{json: {...d, jev_choice: choice, jev_confidence: confidence, jev_cost: (jev.usage || {}).cost, w_keyword}}];

function rrf(rankA, rankB, w, k=60) {
  const scores = {};
  rankA.forEach((id,i) => scores[id] = (scores[id]||0) + w * (1/(k+i+1)));
  rankB.forEach((id,i) => scores[id] = (scores[id]||0) + (1-w) * (1/(k+i+1)));
  return Object.keys(scores).sort((a,b) => scores[b]-scores[a]);
}
const d = $input.first().json;
const fixed_top3 = rrf(d.keyword_rank_live, d.vector_rank_live, 0.5).slice(0,3);
return [{json: {...d, fixed_top3}}];

function rrf(rankA, rankB, w, k=60) {
  const scores = {};
  rankA.forEach((id,i) => scores[id] = (scores[id]||0) + w * (1/(k+i+1)));
  rankB.forEach((id,i) => scores[id] = (scores[id]||0) + (1-w) * (1/(k+i+1)));
  return Object.keys(scores).sort((a,b) => scores[b]-scores[a]);
}
const d = $('RRF fusion: фиксированный вес (0.5)').first().json;
const dynamic_top3 = rrf(d.keyword_rank_live, d.vector_rank_live, d.w_keyword).slice(0,3);
const verdict = dynamic_top3[0] === d.fixed_top3[0] ? 'динамический вес не изменил топ-1' : 'динамический вес ПОДВИНУЛ топ-1 (' + d.fixed_top3[0] + ' -> ' + dynamic_top3[0] + ')';
return [{json: {...d, dynamic_top3, verdict, top1_changed: dynamic_top3[0] !== d.fixed_top3[0], gold_in_dynamic_top1: dynamic_top3[0] === d.gold_doc_id}}];
